import json

def convert(input_jsonl, output_jsonl, output_labels=None, n=10):
    count = 0
    with open(input_jsonl, 'r') as fin, open(output_jsonl, 'w') as fout:
        if output_labels:
            lout = open(output_labels, 'w')
        else:
            lout = None
        for line in fin:
            if count >= n:
                break
            ex = json.loads(line)
            ctx = ex['context']
            options = ex['completions']
            activity_label = ""
            ans = ex.get('answer', None)
            inst = {'ctx': ctx, 'activity_label': activity_label, 'ending_options': options}
            fout.write(json.dumps(inst) + '\n')
            if lout and ans is not None:
                if isinstance(ans,int):
                    lout.write(str(ans)+'\n')
                else:
                    lout.write(str(int(ans.strip()))+'\n')
            count += 1
        if lout:
            lout.close()

if __name__ == "__main__":
    convert('train.jsonl', 'data/hellaswag/train.jsonl', 'data/hellaswag/train-labels.lst', n=10)
    convert('val.jsonl', 'data/hellaswag/valid.jsonl', 'data/hellaswag/valid-labels.lst', n=10)
    convert('test.jsonl', 'data/hellaswag/test.jsonl', None, n=10)

